-- Sepolia 早期验收需要多次真实托管，原 12～42 USDC 报价会过快耗尽测试币。
-- 只更新代码库拥有的固定 Agent；历史候选、已选报价和用户自有 Agent 均保持不变。
BEGIN;

UPDATE agents
   SET price_amount = CASE id
         WHEN '91000000-0000-4000-8000-000000000001' THEN 1500000
         WHEN '91000000-0000-4000-8000-000000000002' THEN 2000000
         WHEN '91000000-0000-4000-8000-000000000003' THEN 3000000
         WHEN '91000000-0000-4000-8000-000000000004' THEN 2000000
         WHEN '91000000-0000-4000-8000-000000000005' THEN 3000000
         WHEN '91000000-0000-4000-8000-000000000006' THEN 4000000
         WHEN '91000000-0000-4000-8000-000000000007' THEN 3000000
         WHEN '91000000-0000-4000-8000-000000000008' THEN 4000000
         WHEN '91000000-0000-4000-8000-000000000009' THEN 5000000
         ELSE price_amount
       END,
       updated_at = now()
 WHERE id IN (
   '91000000-0000-4000-8000-000000000001',
   '91000000-0000-4000-8000-000000000002',
   '91000000-0000-4000-8000-000000000003',
   '91000000-0000-4000-8000-000000000004',
   '91000000-0000-4000-8000-000000000005',
   '91000000-0000-4000-8000-000000000006',
   '91000000-0000-4000-8000-000000000007',
   '91000000-0000-4000-8000-000000000008',
   '91000000-0000-4000-8000-000000000009'
 );

COMMIT;
